  "💬 Alla djur här är ungar. De växer av mat, lek, en leksak och rätt toalett – tidigast unga efter 3 dagar och vuxna efter en vecka.": "💬 All the animals here are babies. They grow with food, play, a toy and the right toilet – young after 3 days at the earliest, grown-up after a week.",
